async function run() {
  const cidade = params.cidade;
  const lat = params.latitude;
  const lon = params.longitude;
  const tz = params.timezone;

  const startDay = dates.startOfDay(now(), 0);
  const endDay = dates.startOfDay(now(), 1);

  const events = await calendar.events({ from: startDay, to: endDay });
  const sortedEvents = events.slice().sort((a, b) => (a.start < b.start ? -1 : a.start > b.start ? 1 : 0));

  const unread = await gmail.search({ query: "in:inbox is:unread", days: 1, unread: true, max: 20 });

  const importantEmails = [];
  for (const email of unread) {
    const verdict = await judge.important(email);
    if (verdict && verdict.p >= 0.5) importantEmails.push(email);
  }

  const url = "https://api.open-meteo.com/v1/forecast?latitude=" + lat +
    "&longitude=" + lon +
    "&daily=temperature_2m_max,temperature_2m_min,precipitation_probability_max" +
    "&timezone=" + encodeURIComponent(tz) +
    "&forecast_days=1";
  const weather = await http.getJSON(url);

  let tmax = null, tmin = null, precip = null;
  if (weather && weather.daily) {
    tmax = weather.daily.temperature_2m_max ? weather.daily.temperature_2m_max[0] : null;
    tmin = weather.daily.temperature_2m_min ? weather.daily.temperature_2m_min[0] : null;
    precip = weather.daily.precipitation_probability_max ? weather.daily.precipitation_probability_max[0] : null;
  }

  const lines = [];
  lines.push("Bom dia! Resumo de " + dates.format(now(), "EEE") + ", " + dates.format(now(), "dd/MM"));
  lines.push("");
  lines.push("Agenda:");
  if (sortedEvents.length === 0) {
    lines.push("• Nenhum evento hoje.");
  } else {
    for (const ev of sortedEvents) {
      if (typeof ev.start === "string" && ev.start.length === 10) {
        lines.push("• (dia todo) " + ev.title);
      } else {
        lines.push("• " + dates.format(ev.start, "HH:mm") + " " + ev.title);
      }
    }
  }
  lines.push("");
  lines.push("Emails importantes:");
  if (importantEmails.length === 0) {
    lines.push("• Nenhum email importante.");
  } else {
    for (const e of importantEmails) {
      lines.push("• " + e.from_name + ": " + e.subject);
    }
  }
  lines.push("");
  if (tmax !== null && tmin !== null) {
    let clima = "Tempo em " + cidade + ": " + tmin + "°C a " + tmax + "°C";
    if (precip !== null) clima += ", " + precip + "% de chance de chuva.";
    else clima += ".";
    lines.push(clima);
  } else {
    lines.push("Tempo em " + cidade + ": previsão indisponível.");
  }

  const text = lines.join("\n");
  log(text);
  await notify.send({ text });
}

async function run() {
  const destinos = params.destinos;
  const diasAntecedencia = params.diasAntecedencia;
  const diasBusca = params.diasBusca;
  const query = params.palavrasChave;

  const emails = await gmail.search({ query, days: diasBusca, max: 30 });

  const paidKeywords = [
    "pagamento confirmado",
    "confirmamos o recebimento",
    "recebemos o pagamento",
    "fatura paga",
    "conta paga",
    "já paga",
    "payment confirmed",
    "payment received",
    "confirmed your payment",
    "invoice paid",
    "we received your payment"
  ];

  const today = dates.today();
  const windowEnd = dates.addDays(today, diasAntecedencia);

  const items = [];

  for (const email of emails) {
    const text = (email.subject || "") + " " + (email.snippet || "");
    const lower = text.toLowerCase();

    const isPaid = paidKeywords.some((k) => lower.includes(k));
    if (isPaid) continue;

    const due = dates.parse(email.snippet || email.subject || "");
    if (!due) continue;

    const amountText = money.find(email.snippet || email.subject || "");
    const amountNum = money.parse(email.snippet || email.subject || "");
    if (!amountText || amountNum === null) continue;

    // must be between today (inclusive) and today+N (inclusive)
    if (dates.isBefore(due, today)) continue;
    if (dates.isBefore(windowEnd, due)) continue;

    items.push({ due, amountText, amountNum, subject: email.subject });
  }

  if (items.length === 0) {
    log("Nenhuma conta vencendo na janela definida.");
    return;
  }

  items.sort((a, b) => (a.due < b.due ? -1 : a.due > b.due ? 1 : 0));

  let total = 0;
  const lines = items.map((it) => {
    total += it.amountNum;
    const dataFmt = dates.format(it.due, "dd/MM");
    return `• ${dataFmt} — ${it.subject}: ${it.amountText}`;
  });

  const totalFmt = money.format(total, "BRL");

  const text =
    `Contas vencendo nos próximos ${diasAntecedencia} dias:\n\n` +
    lines.join("\n") +
    `\n\nTotal: ${totalFmt}`;

  await notify.send({ text });
}

async function run() {
  const emails = await gmail.search({
    query: "in:inbox is:unread",
    unread: true,
    days: params.diasBusca,
    max: 100
  });

  let count = 0;

  for (const e of emails) {
    const j = await judge.newsletter(e);
    if (j.p >= 0.5) {
      await gmail.archive({ id: e.id });
      count++;
    }
  }

  if (count > 0) {
    const noun = count === 1 ? "email" : "emails";
    await notify.send({
      text: `Inbox cleanup: archived ${count} newsletter/promo ${noun}.`
    });
  }
}

async function run() {
  const items = (event && event.items) || [];
  const sender = (params.remetente || "").toLowerCase().trim();

  for (const item of items) {
    const from = (item.from || "").toLowerCase();
    if (sender && !from.includes(sender)) continue;

    const isUnread = item.unread === true || (Array.isArray(item.labels) && item.labels.includes("UNREAD"));
    if (!isUnread) continue;

    const name = item.from_name || item.from || "desconhecido";
    const subject = item.subject || "(sem assunto)";
    const snippet = item.snippet || "";

    const text = `📩 Email de ${name}: "${subject}"\n${snippet}`;
    await notify.send({ text });
  }
}

async function run() {
  const from = dates.startOfDay(now(), 1);
  const to = dates.startOfDay(now(), 8);
  const events = await calendar.events({ from, to });

  const lines = ["Your week ahead:"];

  for (let i = 0; i < 7; i++) {
    const day = dates.addDays(from, i);
    const dayEvents = events
      .filter(e => dates.sameDay(e.start, day))
      .sort((a, b) => (a.start < b.start ? -1 : a.start > b.start ? 1 : 0));

    lines.push("");
    lines.push(dates.format(day, "EEE dd/MM"));

    if (dayEvents.length === 0) {
      lines.push("• nothing scheduled");
    } else {
      for (const e of dayEvents) {
        const timeStr = e.start.length > 10 ? dates.format(e.start, "HH:mm") : "All day";
        lines.push(`• ${timeStr} ${e.title}`);
      }
    }
  }

  const text = lines.join("\n");
  await notify.send({ text });
}

async function run() {
  const query = params.keywords;
  const days = params.days;
  const emails = await gmail.search({ query, days, max: 20 });

  function extractCode(text) {
    if (!text) return null;
    let m = text.match(/(?:tracking\s*(?:number|code)?|rastreio(?:\s*n[uú]mero)?|c[oó]digo de rastreio(?:amento)?|objeto)\s*[:\-]?\s*([A-Za-z0-9]{8,20})/i);
    if (m && m[1]) return m[1].toUpperCase();
    m = text.match(/\b([A-Z]{2}\d{9}[A-Z]{2})\b/);
    if (m) return m[1];
    return null;
  }

  function friendlyStatus(status) {
    if (!status) return "unknown";
    const map = {
      pending: "pending",
      in_transit: "in transit",
      out_for_delivery: "out for delivery",
      delivered: "delivered",
      exception: "exception",
      failed_attempt: "failed delivery attempt",
      returned: "returned to sender",
      customs: "in customs"
    };
    if (map[status]) return map[status];
    return String(status).replace(/_/g, " ");
  }

  const seen = new Set();
  const candidates = [];
  for (const email of emails) {
    const text = `${email.subject || ""} ${email.snippet || ""}`;
    const code = extractCode(text);
    if (!code) continue;
    if (seen.has(code)) continue;
    seen.add(code);
    candidates.push({ email, code });
  }

  const lines = [];
  for (const c of candidates) {
    let result;
    try {
      result = await http.getJSON(`https://api.trackingmore.example/v1/track?code=${encodeURIComponent(c.code)}`);
    } catch (e) {
      result = null;
    }
    if (!result || !result.status) {
      log(`No tracking data for ${c.code}`);
      continue;
    }
    const label = (await write.package_label(c.email)).text;
    const status = friendlyStatus(result.status);
    let line = `• ${c.code} (${label}): ${status}`;
    if (result.last_event) line += ` — ${result.last_event}`;
    if (result.eta) line += `, ETA ${result.eta}`;
    lines.push(line);
  }

  if (lines.length === 0) {
    log("No package tracking updates to report");
    return;
  }

  const text = `📦 Package status\n\n${lines.join("\n")}`;
  await notify.send({ text });
}

async function run() {
  const nowIso = now();
  const tomorrowStart = dates.startOfDay(nowIso, 1);
  const tomorrowEnd = dates.addDays(tomorrowStart, 1);

  const events = await calendar.events({ from: tomorrowStart, to: tomorrowEnd });
  const withGuests = (events || []).filter(e => Array.isArray(e.attendees) && e.attendees.length > 0);

  if (withGuests.length === 0) {
    log('Nenhuma reunião de amanhã com convidados.');
    return;
  }

  withGuests.sort((a, b) => (a.start < b.start ? -1 : a.start > b.start ? 1 : 0));

  const emailCache = {};
  for (const ev of withGuests) {
    for (const attendee of ev.attendees) {
      if (!(attendee in emailCache)) {
        const results = await gmail.search({ query: `from:${attendee}`, days: params.diasBusca, max: params.maxEmails });
        emailCache[attendee] = results || [];
      }
    }
  }

  const sections = [];
  for (const ev of withGuests) {
    const time = dates.format(ev.start, 'HH:mm');
    const lines = [`${time} ${ev.title}`];
    for (const attendee of ev.attendees) {
      const emails = emailCache[attendee] || [];
      for (const item of emails) {
        const resumo = await write.resumoEmail(item);
        const name = item.from_name || item.from;
        const tag = item.replied ? '' : ' (sem resposta)';
        lines.push(`• ${name} — "${item.subject}": ${resumo.text}${tag}`);
      }
    }
    if (lines.length === 1) {
      lines.push('• Sem emails recentes dos participantes');
    }
    sections.push(lines.join('\n'));
  }

  const header = `Preparação para amanhã (${dates.format(tomorrowStart, 'dd/MM')})`;
  const text = header + '\n\n' + sections.join('\n\n');

  await notify.send({ text });
}

async function run() {
  const url = "https://api.exchangerate.example/v1/latest?base=USD&symbols=BRL";
  const data = await http.getJSON(url);
  const rate = data && data.rates && data.rates.BRL;
  if (typeof rate !== "number") {
    log("No BRL rate found in response");
    return;
  }
  log("USD->BRL rate: " + rate);
  const threshold = params.threshold;
  if (rate > threshold) {
    const text = "💵 USD→BRL is at " + rate.toFixed(2) + ", above your " + threshold.toFixed(2) + " threshold.";
    await notify.send({ text });
  } else {
    log("Rate " + rate + " is at or below threshold " + threshold + "; no alert sent");
  }
}

async function run() {
  const minDays = params.minDays;
  const cutoff = dates.addDays(now(), -minDays);
  const emails = await gmail.search({ query: "in:inbox -from:me", days: 30, max: 50 });
  const candidates = emails.filter(e => !e.replied && dates.isBefore(e.date, cutoff));
  const waiting = [];
  for (const e of candidates) {
    const r = await judge.needs_reply(e);
    if (r.p >= 0.5) waiting.push(e);
  }
  if (waiting.length === 0) {
    log("No emails waiting for a reply older than " + minDays + " days.");
    return;
  }
  waiting.sort((a, b) => (dates.isBefore(a.date, b.date) ? -1 : 1));
  const lines = waiting.map(e => `• ${e.from_name} — "${e.subject}" (since ${dates.format(e.date, "MMM d")})`);
  const text = `Waiting on your reply (${minDays}+ days):\n\n${lines.join("\n")}`;
  await notify.send({ text });
}

async function run() {
  const today = dates.today();
  const tomorrow = dates.addDays(today, 1);
  const from = today;
  const to = dates.addDays(today, 2);

  const events = await calendar.events({ from, to });
  log('eventos recebidos: ' + events.length);

  const birthdays = events.filter(e => e.calendar === params.calendarName);

  function extractName(title) {
    if (!title) return title;
    const m = title.match(/^(?:Aniversário de|Aniversário do|Aniversário da|Birthday of|Birthday)\s+(.+)$/i);
    return m ? m[1].trim() : title.trim();
  }

  const todayNames = [];
  const tomorrowNames = [];

  for (const e of birthdays) {
    const name = extractName(e.title);
    if (dates.sameDay(e.start, today)) {
      todayNames.push(name);
    } else if (dates.sameDay(e.start, tomorrow)) {
      tomorrowNames.push(name);
    }
  }

  if (todayNames.length === 0 && tomorrowNames.length === 0) {
    log('nenhum aniversário hoje ou amanhã, nada a enviar');
    return;
  }

  const todayLabel = dates.format(today, "dd/MM");
  const tomorrowLabel = dates.format(tomorrow, "dd/MM");

  let lines = [];
  lines.push('🎂 Aniversários');
  lines.push('');
  lines.push('Hoje (' + todayLabel + '): ' + (todayNames.length ? todayNames.join(', ') : 'ninguém'));
  lines.push('Amanhã (' + tomorrowLabel + '): ' + (tomorrowNames.length ? tomorrowNames.join(', ') : 'ninguém'));

  await notify.send({ text: lines.join('\n') });
}
